package pl.maciek.squashscoreboard;

import android.app.Activity;import android.graphics.Color;import android.os.Bundle;import android.text.TextUtils;import android.view.*;import android.widget.*;import java.util.*;
public class PlayerComparisonActivity extends Activity {
 private PlayerProfile one,two; private int bg,fg,muted;
 @Override public void onCreate(Bundle b){super.onCreate(b);draw();}
 private void draw(){one=ProfileStore.find(this,getIntent().getStringExtra("one"));two=ProfileStore.find(this,getIntent().getStringExtra("two"));if(one==null||two==null){finish();return;}boolean dark=AppPreferences.dark(this);bg=dark?Color.rgb(13,16,22):Color.rgb(245,247,250);fg=dark?Color.WHITE:Color.rgb(24,30,40);muted=dark?Color.rgb(174,185,201):Color.rgb(80,92,108);PlayerStatistics.Summary a=PlayerStatistics.calculate(this,one),b=PlayerStatistics.calculate(this,two);int[] h2h=headToHead();LinearLayout root=box(bg);root.setPadding(dp(18),dp(12),dp(18),dp(12));TextView back=text("<  GRACZE",17,muted);back.setOnClickListener(v->finish());root.addView(back,new LinearLayout.LayoutParams(-1,dp(34)));TextView title=text("POROWNANIE GRACZY",24,fg);title.setGravity(Gravity.CENTER);root.addView(title,new LinearLayout.LayoutParams(-1,dp(42)));ScrollView scroll=new ScrollView(this);LinearLayout table=box(bg);table.addView(headerRow(),new LinearLayout.LayoutParams(-1,dp(50)));String[] labels={"Mecze","Wygrane","Skutecznosc","Punkty","Sr. pkt/mecz","6-7 / 7-6","6-9 / 9-6"};String[] left={String.valueOf(a.matches),String.valueOf(a.wins),pct(a.wins,a.matches)+"%",String.valueOf(a.points),avg(a.points,a.matches),String.valueOf(a.score67),String.valueOf(a.score69)};String[] right={String.valueOf(b.matches),String.valueOf(b.wins),pct(b.wins,b.matches)+"%",String.valueOf(b.points),avg(b.points,b.matches),String.valueOf(b.score67),String.valueOf(b.score69)};for(int i=0;i<labels.length;i++)table.addView(statRow(left[i],labels[i],right[i]),new LinearLayout.LayoutParams(-1,dp(40)));scroll.addView(table);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView direct=text("BILANS BEZPOSREDNI: "+one.name+" "+h2h[1]+" : "+h2h[2]+" "+two.name+"   (mecze: "+h2h[0]+")",17,muted);direct.setGravity(Gravity.CENTER);root.addView(direct,new LinearLayout.LayoutParams(-1,dp(38)));setContentView(root);}
 private LinearLayout headerRow(){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView first=cell("● "+one.name,18,one.color);first.setSingleLine(true);first.setEllipsize(TextUtils.TruncateAt.END);TextView middle=cell("STATYSTYKA",14,muted);TextView second=cell("● "+two.name,18,two.color);second.setSingleLine(true);second.setEllipsize(TextUtils.TruncateAt.END);row.addView(first,new LinearLayout.LayoutParams(0,-1,1));row.addView(middle,new LinearLayout.LayoutParams(dp(150),-1));row.addView(second,new LinearLayout.LayoutParams(0,-1,1));return row;}
 private LinearLayout statRow(String left,String label,String right){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(cell(left,18,one.color),new LinearLayout.LayoutParams(0,-1,1));row.addView(cell(label,15,muted),new LinearLayout.LayoutParams(dp(150),-1));row.addView(cell(right,18,two.color),new LinearLayout.LayoutParams(0,-1,1));return row;}
 private TextView cell(String value,int size,int color){TextView v=text(value,size,color);v.setGravity(Gravity.CENTER);return v;}
 private int[] headToHead(){int[] out=new int[3];for(MatchRecord r:MatchHistoryStore.load(this)){boolean oneFirst=PlayerStatistics.belongs(r,true,one)&&PlayerStatistics.belongs(r,false,two),twoFirst=PlayerStatistics.belongs(r,true,two)&&PlayerStatistics.belongs(r,false,one);if(!oneFirst&&!twoFirst)continue;out[0]++;int winner=r.statisticalWinner();if(winner==0)continue;if((oneFirst&&winner==1)||(twoFirst&&winner==2))out[1]++;else out[2]++;}return out;}
 private LinearLayout box(int c){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setBackgroundColor(c);return x;}private TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);return v;}private String avg(int a,int b){return b==0?"0":String.format(Locale.US,"%.1f",a/(float)b);}private String pct(int a,int b){return b==0?"0":String.valueOf(Math.round(a*100f/b));}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}
